import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Plan Ekranı - Toparlanma Noktaları","description":"","frontmatter":{},"headers":[],"relativePath":"tr/qgc-user-guide/plan_view/plan_rally_points.md","filePath":"tr/qgc-user-guide/plan_view/plan_rally_points.md"}`),a={name:`tr/qgc-user-guide/plan_view/plan_rally_points.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-ekranı-toparlanma-noktaları" tabindex="-1">Plan Ekranı - Toparlanma Noktaları <a class="header-anchor" href="#plan-ekranı-toparlanma-noktaları" aria-label="Permalink to “Plan Ekranı - Toparlanma Noktaları”">​</a></h1><p>Toparlanma noktaları, iniş ya da oyalanma noktalarına alternatif noktalardır. Genellikle Geri Dönüş / RTL modunda ana konumdan daha güvenli veya daha uygun (örneğin daha yakın) bir varış noktası sağlamak için kullanılırlar.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p><em>QGroundControl</em> will not display the Rally Point options if they are not supported by the connected vehicle firmware.</p></div><h2 id="rally-point-usage" tabindex="-1">Rally Point Usage <a class="header-anchor" href="#rally-point-usage" aria-label="Permalink to “Rally Point Usage”">​</a></h2><p>Toparlanma Noktası oluşturmak için:</p><ol><li>Plan Ekranı&#39;na gidin</li><li>Select the <strong>Rally Points</strong> layer using the <a href="./plan_view.html#layer-switcher">Layer Switcher</a> in the top-right area of the map (or expand the <strong>Rally Points</strong> section in the <a href="./plan_view.html#plan-editor-panel">Plan Editor Panel</a>)</li><li>Haritanın neresinde toparlanma noktası olmasını istiyorsanız tıklayın. <ul><li>Her biri için bir <strong>R</strong> işareti eklenir</li><li>The currently active marker has a different color (green) and its editor is expanded in the <em>Rally Points</em> section.</li></ul></li><li>Make any rally point active by selecting it on the map or in the <em>Rally Points</em> section: <ul><li>Move the active rally point by either dragging it on the map or editing the position fields in its editor.</li><li>Delete a rally point by pressing the <strong>X</strong> delete button on its editor.</li></ul></li></ol><h2 id="upload-rally-points" tabindex="-1">Upload Rally Points <a class="header-anchor" href="#upload-rally-points" aria-label="Permalink to “Upload Rally Points”">​</a></h2><p>Rally points are uploaded along with the rest of the plan using the <strong>Upload</strong> button in the <a href="./plan_view.html#file">Plan Toolbar</a>.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};